/* From Uiverse.io by aadium - Tags: button, car, formula1 */
.__UIV_SCOPE__ .carbutton {
  width: 200px;
  height: 70px;
  padding: 20px;
  background: #212121;
  border: 6px double #e8e8e8;
  transition: 0.2s;
}

.__UIV_SCOPE__ .caption {
  color: #e8e8e8;
  font-family: 'Courier New', Courier, monospace;
  font-size: 20px;
  transition: 0.2s;
}

.__UIV_SCOPE__ .car {
  fill: #e8e8e8;
  width: 50px;
  height: 50px;
  margin-left: -120px;
  margin-top: -35px;
  transition: 0.2s ease-in-out;
}

.__UIV_SCOPE__ .carbutton:not(:hover) .car {
  opacity: 0%;
  transform: translateX(-150px);
}

.__UIV_SCOPE__ .carbutton:hover .caption {
  opacity: 0%;
}

.__UIV_SCOPE__ .carbutton:focus .car {
  transform: translateX(120px);
}
